mapper.select:
select * from internship_stage_assignment
where application_id = #{applicationId}
order by id desc limit 1

select * from internship_stage_assignment
where source_type = #{sourceType} and source_assignment_id = #{sourceId}
order by id desc limit 1

select * from internship_stage_assignment
where confirmation_record_id = #{confirmationRecordId}
order by current_flag desc, id desc limit 1

select * from internship_stage_assignment
where student_id = #{studentId}
order by stage_no asc, sequence_no asc, id asc

select * from internship_stage_assignment
where student_id = #{studentId}
  and company_id = #{companyId}
  and position_id = #{positionId}
  and status = 'PENDING_CONFIRMATION'
  and current_flag = 0
order by id desc limit 1

mapper.update:
update internship_stage_assignment
source_type = #{sourceType}, source_assignment_id = #{sourceAssignmentId}, application_id = #{applicationId}, confirmation_record_id = #{confirmationRecordId}, company_id = #{companyId}, company_name = #{companyName}, position_id = #{positionId}, position_name = #{positionName}, internship_start_time = #{internshipStartTime}, internship_end_time = #{internshipEndTime}, status = #{status}, current_flag = #{currentFlag}, remark = #{remark}, update_time = now()
where id = #{id}
